import React from 'react';
import './costing.css'; 


const CostingPage = () => (
  <div className="costing-container">
    <div className="content-section">
      <h2>අගය ඇස්තමේන්තු කිරීම</h2>
      <p>
        ඔබගේ නිමාවට අගය ඇස්තමේන්තු කිරීම සඳහා Embroidery, Screen printing, Buttons,
        Stones, Labels, Contrast fabric එකතුව ඇස්තමේන්තු කිරීම, පටත්, Tie and Dye wash
        කිරීම සහ වෙනත් ක්‍රියාකාරකම් ඇතුළත් වේ.<br /><br />
        ඇස්තමේන්තු කරන මෙවලම් සියල්ල, හා එවැනි සෑදූ නිමාවට අනුව පිරිවැය සැලැස්වීම අත්‍යවශ්‍ය වේ.<br /><br />
        වැඩි විස්තර සදහා “About Me” බොත්තම ක්ලික් කරන්න.
      </p>
    </div>
    <div className="image-section">
      <img src="/Images/costing.jpeg" alt="Dress Work Process" />
    </div>
  </div>
);

export default CostingPage;
